import java.io.*;
public class FileHandler { public static void append(String filename,String line){File file=new File(filename);File parent=file.getParentFile();if(parent!=null&&!parent.exists())parent.mkdirs();try(BufferedWriter writer=new BufferedWriter(new FileWriter(file,true))){writer.write(line);writer.newLine();}catch(IOException ex){System.out.println("Could not save data to "+filename+": "+ex.getMessage());}} public static void ensureFile(String filename){try{File f=new File(filename);File p=f.getParentFile();if(p!=null)p.mkdirs();if(!f.exists())f.createNewFile();}catch(IOException ex){System.out.println(ex.getMessage());}} }
